Lemma dequeue_exhausted_ok st LS m :
  INVL X st L BL LS -> active st sc = Some m -> m_avail (MR st m) = 0 -> m_freed (MR st m) = 0 ->
  exists LS' rest, INVL X (dequeue (LActive sc) m st) L BL LS' /\ LS (LActive sc) = m :: rest
